arguments.command:
python3 -u - <<'EOF'
import numpy as np, collections, pickle
e=np.load('data/beh/Imaging_Exp_info.npy',allow_pickle=1).item()
rec=collections.defaultdict(list)
for et,v in e.items():
    for d in v:
        kn='%s_%s_%s'%(d['mname'],d['datexp'],d['blk'])
        kn2=kn+'_'+d['stimtype'] if 'stimtype' in d else kn
        rec[kn].append((et,kn2,d))
# merged stim map
stimmap={}
for kn,l in rec.items():
    sm={}
    for et,kn2,d in l:
        pass
    stimmap[kn]=sm
cnt=collections.Counter(); rewcnt=collections.Counter(); nrewsess=0
walls=collections.Counter()
per={}
for et in e.keys():
    B=np.load('data/beh/Beh_'+et+'.npy',allow_pickle=1).item()
    for kn,l in rec.items():
        for (etx,kn2,d) in l:
            if etx!=et: continue
            b=B[kn2]
            sm=stimmap[kn]
            for w,sid in zip(b['UniqWalls'], d['stim_id']):
                if not np.isnan(sid): sm[str(w)]=int(sid)
            if kn not in per:
                per[kn]={'WallName':np.array([str(x) for x in b['WallName']]),'isRew':b['isRew'].copy(),'ntrials':int(b['ntrials'])}
tot=0
for kn,p in per.items():
    sm=stimmap[kn]
    wn=p['WallName']; isr=p['isRew']
    rewstim = wn[isr][0] if isr.any() else None
    rewcorr = (wn==rewstim) if rewstim else np.zeros(len(wn),bool)
    if rewstim: nrewsess+=1
    for w in wn: walls[w]+=1
    sid=np.array([sm.get(w,-1) for w in wn])
    cnt.update(sid.tolist())
    rewcnt[int(rewcorr.sum())]+=0
    tot+=len(wn)
    per[kn]['rewcorr']=rewcorr; per[kn]['sid']=sid
print('total trials',tot)
print('stim id counts',sorted(cnt.items()))
print('frac', {k:round(v/tot,4) for k,v in sorted(cnt.items())})
print('walls',walls)
print('sessions with reward',nrewsess)
nrew=sum(p['rewcorr'].sum() for p in per.values()); print('rewarded-corridor trials',nrew, nrew/tot)
# unassigned wall names
un=collections.Counter()
for kn,p in per.items():
    for w,s in zip(p['WallName'],p['sid']):
        if s==-1: un[(kn,w)]+=1
print('unassigned',un)
EOF

